<script setup lang="ts">import{onMounted,computed}from 'vue';import{runs,loadRuns}from '../stores/runs';import{samples,loadBatches}from '../stores/samples';import{reviews,loadReviews}from '../stores/reviews';import{chains,loadChains}from '../stores/chains';import{useTask}from '../hooks/useTask';import PageHeading from '../components/common/PageHeading.vue';import CalibrationSummary from '../components/CalibrationSummary.vue';import MarginTable from '../components/MarginTable.vue';import RunTable from '../components/RunTable.vue';import ErrorNotice from '../components/common/ErrorNotice.vue';import{chainStatusLabels}from '../constants/enums';const{error,execute}=useTask();const latest=computed(()=>runs.items.find(r=>r.status==='completed'&&r.result?.sample_count));const refresh=()=>execute(async()=>{await Promise.all([loadRuns(),loadBatches(),loadReviews(),loadChains()])});onMounted(refresh);</script><template><PageHeading index="01" title="先看见偏差，再讨论代表性" subtitle="原野交通研究所 · 匿名出行样本的边际校准、权重交付与逐月链式比较。"/><ErrorNotice :message="error" @retry="refresh"/><div class="overview-intro"><section><p class="eyebrow">THE WEIGHT OF A SAMPLE</p><h2>城市的比例，<br>不会自动出现在样本里。</h2><p>逐维匹配居住分区、年龄组与出行方式，同时检查收敛残差、极端权重和有效样本量；逐月差值再按冻结口径分解为人群构成与时长贡献。</p><RouterLink to="/calibrations" class="primary link-button">建立一次校准 →</RouterLink></section><aside><div><b>{{samples.batches.length}}</b><span>样本批次</span></div><div><b>{{samples.batches.reduce((a,b)=>a+b.sample_count,0)}}</b><span>匿名出行样本</span></div><div><b>{{reviews.items.filter(r=>r.decision==='approved').length}}</b><span>已批准权重口径</span></div><div><b>{{chains.items.length}}</b><span>链式比较组</span></div></aside></div><template v-if="chains.items.length"><div class="section-heading"><h2>链式比较 / 冻结共同口径的逐月分解</h2><RouterLink to="/chains">全部链 ↗</RouterLink></div><div class="table-wrap"><table><thead><tr><th>比较组</th><th>链状态</th><th>工作版本</th><th>已发布</th><th></th></tr></thead><tbody><tr v-for="g in chains.items.slice(0,3)" :key="g.id"><td><strong>{{g.name}}</strong></td><td><span class="badge" :class="g.status">{{chainStatusLabels[g.status]||g.status}}</span></td><td>v{{g.version}}</td><td>{{g.published_version?('v'+g.published_version):'未发布'}}</td><td><RouterLink :to="'/chains/'+g.id">依赖与对账 ↗</RouterLink></td></tr></tbody></table></div></template><template v-if="latest?.result"><div class="section-heading"><h2>最近一次研究 / {{latest.name}}</h2><RouterLink :to="'/results/'+latest.id">完整诊断 ↗</RouterLink></div><CalibrationSummary :result="latest.result"/><MarginTable :items="latest.result.diagnostics"/></template><div class="section-heading"><h2>校准档案</h2><RouterLink to="/calibrations">全部运行 ↗</RouterLink></div><RunTable :items="runs.items.slice(0,4)"/></template>
